function cancelRequest() {
  reportUserClosed();
  window.close();
}

function reportUserClosed() {
  const request = window.arguments[0]?.wrappedJSObject;
  // Bug 1879038: This is also called for WebExtension popup windows, but they do
  // not send a request.
  if (!request) {
    return;
  }
  request.cancelled();
}
